48:     public:
49:         static std::shared_ptr<library_private> create_or_find_library(string_view file_name, string_view version)
50:         {
51:             auto& manager = get_instance();
52:             std::lock_guard<std::mutex> lock(manager.m_library_mutex);
53: 
54:             auto file_as_string = file_name.to_string();
55:             auto itr = manager.m_library_map.find(file_as_string);
56:             if (itr != manager.m_library_map.end())
57:                 return itr->second;
58: 
59:             auto lib = std::make_shared<library_private>(file_name, version);
60: 
61:             manager.m_library_map.emplace(std::move(file_as_string), lib);
62: 
63:             return lib;
64:         }
