66:         ~library_manager()
67:         {
68:             clean_all_libs();
69:         }
70: 
71:         static void remove_item(const std::shared_ptr<library_private>& item)
72:         {
73:             auto& manager = get_instance();
74:             std::lock_guard<std::mutex> lock(manager.m_library_mutex);
75: 
76:             auto itr = manager.m_library_map.find(item->get_file_name().to_string()); // because we use string_view to find the item
77:             if (itr != manager.m_library_map.end())
78:                 manager.m_library_map.erase(itr);
79:         }
80: 
81:     private:
82:         library_manager() {}
83: 
84:         static library_manager& get_instance()
85:         {
86:             static library_manager obj;
87:             return obj;
88:         }
89: 
90:         void clean_all_libs()
91:         {
92:             for (auto& item : m_library_map)
93:             {
94:                 // only the manager holds library pointer, thus we can now unload
95:                 if (item.second.use_count() == 1)
96:                 {
97:                     item.second->set_load_count(1); // this will implicit force an unload of the library
98:                     item.second->unload();
99:                 }
100:             }
101:         }
102: 
103:         // use std::less in order to use string_view for finding the item
104:         std::map<std::string, std::shared_ptr<library_private>> m_library_map;
105:         std::mutex m_library_mutex;
