50: /*!
51:  * This class contains the private implementation of the \ref library class.
52:  *
53:  */
54: class RTTR_LOCAL library_private
55: {
56: public:
57:     library_private(string_view file_name, string_view version)
58:     :   m_file_name(file_name),
59:         m_version(version),
60:         m_load_count(0),
61:         m_handle(nullptr)
62:     {
63: 
64:     }
65: 
66:     ~library_private() = default;
67: 
68:     bool load()
69:     {
70:         if (m_handle)
71:         {
72:             ++m_load_count;
73:             return true;
74:         }
75:         m_state_saver.save_state_begin();
76: 
77:         auto result = load_native();
78:         if (result)
79:         {
80:             ++m_load_count;
81:             m_state_saver.save_state_end();
82:         }
83:         else
84:         {
85:             m_state_saver.reset();
86:         }
87: 
88:         return result;
89:     }
90: 
91:     bool unload()
92:     {
93:         if (!m_handle)
94:             return false;
95: 
96:         --m_load_count;
97: 
98:         if (m_load_count.load() == 0)
99:         {
100:             auto ret = unload_native();
101:             if (ret)
102:             {
103:                 m_error_string.clear();
104:                 m_state_saver.reset();
105:                 m_handle = nullptr;
106:             }
107:         }
108: 
109:         return (m_handle == nullptr);
110:     }
111: 
